import{_ as t,o,c as a,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"FR 3.7.14 — Suggest Hashtag Trend","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/06-ai-features/3-7-14-suggest-hashtag-trend/spec.md","filePath":"feature/srs/06-ai-features/3-7-14-suggest-hashtag-trend/spec.md"}'),n={name:"feature/srs/06-ai-features/3-7-14-suggest-hashtag-trend/spec.md"};function s(c,e,r,i,l,g){return o(),a("div",null,[...e[0]||(e[0]=[d('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-7-14-—-suggest-hashtag-trend" tabindex="-1">FR 3.7.14 — Suggest Hashtag Trend <a class="header-anchor" href="#fr-3-7-14-—-suggest-hashtag-trend" aria-label="Permalink to &quot;FR 3.7.14 — Suggest Hashtag Trend&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.7.14</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-101</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Suggest Hashtag Trend (Contextual, Workspace-Aware &amp; Trend-Grounded)</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">AI Features (<code>3.7</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20</code>, <code>BR-45</code>, <code>BR-50</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01</code>, <code>MSG02</code>, <code>MSG03</code>, <code>MSG07</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified (Consolidates <code>api-hashtag-suggestions</code>, <code>contextual-hashtag-suggestions</code>, <code>workspace-context-hashtag-suggestions</code>, <code>workspace-hashtag-demo-seed</code>)</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Provide ranked, contextually accurate, platform-clamped hashtag suggestions inside the Post/Task Content Editor (<code>AiHashtagSuggestions.tsx</code>, <code>HashtagInputWithSuggestions.tsx</code>) and Hashtag Collection workflow for <code>Owner</code>, <code>Manager</code>, and <code>Creator</code>. The pipeline combines:</p><ol><li><strong>Caption Semantic Meaning First:</strong> Gemini (<code>GEMINI_MODEL</code>) interprets caption intent, target audience, topic, and tone, treating caption text strictly as untrusted data (prompt-injection safe).</li><li><strong>Authorized Workspace Candidate Enrichment:</strong> <code>HashtagSuggestionContext</code> in <code>brandhub-business-service</code> loads up to <code>500</code> active optional hashtags (<code>BRAND</code>, <code>CAMPAIGN</code>, <code>TRENDING</code>) from <code>workspace_hashtags</code> for the caller&#39;s authorized Workspace (preferring <code>BRAND</code> then recent entries, excluding soft-deleted and <code>EVENT_SPECIFIC</code>/required campaign tags, and overwriting any caller-spoofed <code>workspace_hashtags</code>).</li><li><strong>Evidence-Based Trend Grounding:</strong> Optional cached Redis trend evidence (<code>trends:vn:live:{category}</code>) enriches suggestions without ever fabricating trend badges or padding results with unrelated viral topics (e.g., excluding <code>#WorldCup</code> on a student laptop post).</li></ol><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an <code>Owner</code>, <code>Manager</code>, or <code>Creator</code> drafting social content for Facebook, Instagram, TikTok, or Threads, I want to generate ranked hashtag suggestions with transparent provenance (<code>WORKSPACE</code>, <code>TREND_CONTEXT</code>, <code>AI_GENERATED</code>) and click to insert selected tags into my post without mutating the Workspace Hashtag Collection unless I explicitly save them.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Role, Tenant &amp; Spoofing Protection (<code>BR-20</code>):</strong> Authenticated <code>Owner</code>, <code>Manager</code>, and <code>Creator</code> invoke <code>POST /api/v1/ai/content/hashtags</code> via <code>AiGenerationController</code>. <code>HashtagSuggestionContext</code> queries <code>workspace_hashtags</code> exclusively for the server-verified <code>workspaceId</code> after <code>HASHTAG_GENERATE</code> credit reservation claim, ignoring any client-supplied <code>client_id</code> or <code>workspace_hashtags</code> array.</li><li><strong>Relevance Ranking &amp; Provenance Badges (<code>BR-50</code>):</strong> Suggestions return in descending relevance order with deterministic <code>source</code> derived from Unicode NFC + accent-insensitive membership verification: <ul><li><code>WORKSPACE</code> — matched an active tag in the authorized Workspace&#39;s <code>workspace_hashtags</code> collection.</li><li><code>TREND_CONTEXT</code> — matched verified Redis trend cache evidence (<code>trends:vn:*</code>) relevant to the caption.</li><li><code>AI_GENERATED</code> — contextually synthesized niche/topical hashtag when neither workspace nor trend cache covers the concept.</li></ul></li><li><strong>Platform Clamping &amp; Sanitization:</strong> Supported platforms are strictly <code>facebook</code> (recommended 3–5), <code>instagram</code> (up to 30), <code>tiktok</code> (recommended 5–8), and <code>threads</code> (1–3). Output tags enforce single leading <code>#</code>, Unicode NFC letters/marks/digits/underscores (<code>&lt;= 100</code> chars), case/accent-insensitive deduplication, and community-safety blacklist filtering.</li><li><strong>Explicit User Selection (No Silent Mutation):</strong> Empty captions disable the Generate button. Clicking a suggested chip appends it once to the active post draft (preventing duplicates) and never auto-inserts into <code>workspace_hashtags</code> unless the user explicitly invokes <code>HashtagController</code> (<code>POST /api/v1/workspaces/{workspaceId}/hashtags</code>).</li><li><strong>Credit Accounting &amp; Failure Safety:</strong> Managed through <code>AiCreditGenerationService</code> (<code>HASHTAG_GENERATE</code>). Explicit <code>HASHTAG_GENERATION_FAILED</code> / <code>HASHTAG_GENERATION_UNAVAILABLE</code> or pre-dispatch context load failure finalizes <code>0</code> billable units (releases reservation); transient upstream <code>503</code> triggers fallback model retry with trace-correlated, caption/secret-redacted structured logs.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Key-parallel <code>editor.hashtagInput.aiGenerate</code>, <code>aiLoading</code>, <code>aiResults</code>, <code>aiRankHint</code>, <code>aiEmpty</code>, <code>sourceWorkspace</code>, <code>sourceTrend</code>, and <code>sourceGenerated</code> in <code>src/i18n/locales/{vi,en}/editor.json</code> (plus <code>hashtagService.ts</code> + <code>tr()</code> on Mobile).</li><li><strong>Light &amp; Dark Mode Compliance:</strong> Numbered suggestion list, provenance badges, keyboard focus rings, and responsive chip wrapping use semantic theme tokens across <code>375px</code>, <code>768px</code>, and <code>1440px</code> viewports in both Light and Dark modes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Components:</strong> <code>pages/editor/components/AiHashtagSuggestions.tsx</code>, <code>HashtagInputWithSuggestions.tsx</code>, <code>HashtagCollectionPicker.tsx</code>, and <code>pages/hashtag-groups/index.tsx</code>.</li><li><strong>Mobile Components:</strong> <code>src/services/hashtagService.ts</code>, <code>src/screens/more/AiPostStudioScreen.tsx</code>.</li><li><strong>UI States:</strong><ul><li><strong>Disabled:</strong> Empty/whitespace-only caption disables <code>aiGenerate</code> trigger with tooltip guidance.</li><li><strong>Loading:</strong> Inline skeleton/spinner (<code>editor.hashtagInput.aiLoading</code>) with query cancellation if caption/platform changes.</li><li><strong>Ranked Results:</strong> Numbered vertical list (<code>#1..#N</code>) showing <code>#TagName</code> + provenance pill (<code>sourceWorkspace</code> / <code>sourceTrend</code> / <code>sourceGenerated</code>); already-selected tags show check state and prevent duplicate insertion.</li><li><strong>Empty / Error:</strong> Explicit retryable banner (<code>aiEmpty</code> / localized error) with zero mock/unrelated fallback tags.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth</th><th style="text-align:left;">Handler</th><th style="text-align:left;">Request / Response</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST /api/v1/ai/content/hashtags</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>AiGenerationController</code> -&gt; <code>AiCreditGenerationService</code></td><td style="text-align:left;">Req: <code>{ workspaceId, caption, platform, count }</code> -&gt; <code>200 ApiResponse&lt;HashtagGenerateResponse&gt;</code> (<code>hashtags[]</code> + <code>suggestions[{ tag, source, score }]</code>)</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/ai/content/hashtags</code> (Internal)</td><td style="text-align:left;"><code>X-Internal-Api-Key</code></td><td style="text-align:left;"><code>brandhub-ai-service</code> <code>app/api/v1/endpoints/content.py</code></td><td style="text-align:left;">Receives caption + validated <code>workspace_hashtags</code> (<code>&lt;= 500</code>) + platform/count; queries Gemini + <code>trend_cache_service.py</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/hashtags</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>HashtagController</code></td><td style="text-align:left;">Optional explicit save into <code>workspace_hashtags</code> (<code>BRAND</code>, <code>CAMPAIGN</code>, <code>TRENDING</code>, <code>EVENT_SPECIFIC</code>)</td></tr></tbody></table><h2 id="_6-error-handling-seed-integrity-edge-cases" tabindex="-1">6. Error Handling, Seed Integrity &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-seed-integrity-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Seed Integrity &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Empty Workspace Collection:</strong> Works seamlessly (<code>workspace_hashtags = []</code>), returning <code>TREND_CONTEXT</code> and <code>AI_GENERATED</code> tags without error.</li><li><strong>Required / <code>EVENT_SPECIFIC</code> Campaign Tags:</strong> Excluded from optional AI candidate pool so mandatory campaign hashtag compliance rules remain enforced independently.</li><li><strong>Idempotent Demo Seed Compatibility:</strong> Transactional <code>workspace_hashtags</code> demo/trend-import migrations use NFC normalization, lowercase uniqueness conflict guards (<code>ON CONFLICT DO NOTHING</code>), and preserve soft-deleted rows across reruns.</li><li><strong>Log Redaction:</strong> Lifecycle logs record trace ID, provider branch, latency, and result count while redacting raw caption bodies and <code>GEMINI_API_KEY</code>.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Sibling SRS FRs:</strong> <a href="./../3-7-1-view-trending-topics-suggestions/spec.html">FR 3.7.1 — View Trending Topics Suggestions</a> · <a href="./../3-7-6-generate-caption/spec.html">FR 3.7.6 — Generate Caption</a></li><li><strong>Consolidated Extension Module:</strong> <a href="./../../../modules/05-ai-rag-and-crawler/rag-caption-moderation-and-humanizer/spec.html"><code>rag-caption-moderation-and-humanizer</code></a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/06-ai-features.html">BA 3.7 AI Features</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified in <code>AiGenerationControllerTest</code>, <code>AiHashtagFailureTest</code>, <code>26</code> AI hashtag unit tests, and Playwright <code>vi</code>/<code>en</code> Light/Dark studio tests (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> Post-publish hashtag impression analytics (covered in FR 3.8.4) and unsupported platforms outside Facebook, Instagram, TikTok, and Threads.</li></ul>',20)])])}const u=t(n,[["render",s]]);export{p as __pageData,u as default};
